<?php
require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);
$s=$conn->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1');$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();
if(!$p){http_response_code(404);render_header('Product not found');echo '<div class="empty-state"><h2>Product not found</h2><a href="'.e(url()).'">Back to shop</a></div>';render_footer();exit;}
render_header($p['name']);?><div class="detail-grid"><div class="detail-image"><img src="<?=e(image_path($p['image']))?>" alt="<?=e($p['name'])?>"></div><div class="detail-copy"><span class="eyebrow"><?=e($p['category_name'])?></span><h1><?=e($p['name'])?></h1><p class="detail-price"><?=money($p['price'])?></p><p><?=nl2br(e($p['description']??''))?></p><p class="muted"><?=((int)$p['stock']>0)?'Available · '.$p['stock'].' in stock':'Currently out of stock'?></p><form method="post" action="<?=e(url('cart.php'))?>" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Quantity <input type="number" name="quantity" min="1" max="<?=max(1,(int)$p['stock'])?>" value="1"></label><button class="button" <?=((int)$p['stock']<1?'disabled':'')?>>Add to cart</button></form><form method="post" action="<?=e(url('wishlist.php'))?>"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="button secondary">♡ Add to wishlist</button></form></div></div><?php render_footer();?>
